package mining_threat_retreat_supervision.Mining_Threat_Retreat_Supervision

import org.sireum._
import art._
import mining_threat_retreat_supervision._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Threat_Observation_Api {
  def id: Art.BridgeId
  def threat_sample_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var threat_sample: Mining_Threat_Retreat_Supervision.ThreatSampleValue = $

  def put_threat_sample(value : Mining_Threat_Retreat_Supervision.ThreatSampleValue) : Unit = {
    Contract(
      Modifies(threat_sample),
      Ensures(
        threat_sample == value
      )
    )
    Spec {
      threat_sample = value
    }

    Art.putValue(threat_sample_Id, Mining_Threat_Retreat_Supervision.ThreatSampleValue_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Threat_Observation_Initialization_Api (
  val id: Art.BridgeId,
  val threat_sample_Id : Art.PortId) extends Threat_Observation_Api

@datatype class Threat_Observation_Operational_Api (
  val id: Art.BridgeId,
  val threat_sample_Id : Art.PortId) extends Threat_Observation_Api {

}
